bool mpz_as_int_checked(const mpz_t *i, mp_int_t *value) {
    mp_uint_t val = 0;
    mpz_dig_t *d = i->dig + i->len;

    while (d-- > i->dig) {
        if (val > (~(MP_OBJ_WORD_MSBIT_HIGH) >> mpz_hub.dig_size)) {
            // will overflow
            return false;
        }
        val = (val << mpz_hub.dig_size) | *d;
    }

    if (i->neg != 0) {
        val = -val;
    }

    *value = val;
    return true;
}

bool mpz_as_uint_checked(const mpz_t *i, mp_uint_t *value) {
    if (i->neg != 0) {
        // can't represent signed values
        return false;
    }

    mp_uint_t val = 0;
    mpz_dig_t *d = i->dig + i->len;

    while (d-- > i->dig) {
        if (val > (~(MP_OBJ_WORD_MSBIT_HIGH) >> (mpz_hub.dig_size - 1))) {
            // will overflow
            return false;
        }
        val = (val << mpz_hub.dig_size) | *d;
    }

    *value = val;
    return true;
}

bool mpz_as_bytes(const mpz_t *z, bool big_endian, bool as_signed, size_t len, byte *buf) {
    byte *b = buf;
    if (big_endian) {
        b += len;
    }
    mpz_dig_t *zdig = z->dig;
    int bits = 0;
    mpz_dbl_dig_t d = 0;
    mpz_dbl_dig_t carry = 1;
    size_t olen = len; // bytes in output buffer
    bool ok = true;
    for (size_t zlen = z->len; zlen > 0; --zlen) {
        bits += mpz_hub.dig_size;
        d = (d << mpz_hub.dig_size) | *zdig++;
        for (; bits >= 8; bits -= 8, d >>= 8) {
            mpz_dig_t val = d;
            if (z->neg) {
                val = (~val & 0xff) + carry;
                carry = val >> 8;
            }

            if (!olen) {
                // Buffer is full, only OK if all remaining bytes are zeroes
                ok = ok && ((byte)val == 0);
                continue;
            }

            if (big_endian) {
                *--b = val;
            } else {
                *b++ = val;
            }
            olen--;
        }
    }

    if (as_signed && olen == 0 && len > 0) {
        // If output exhausted then ensure there was enough space for the sign bit
        byte most_sig = big_endian ? buf[0] : buf[len - 1];
        ok = ok && (bool)(most_sig & 0x80) == (bool)z->neg;
    } else {
        // fill remainder of buf with zero/sign extension of the integer
        memset(big_endian ? buf : b, z->neg ? 0xff : 0x00, olen);
    }

    return ok;
}

